/**
 * The Java SDK's zero-op package, as files (bit 16 phase a, R5, D5): the file set and each file byte for byte. The
 * pinned bytes are google-java-format's canonical form, which format.test.ts holds to GJF and to javac. Also the
 * builder's shape, the transport built once on `followRedirects(NEVER)` with no `close()` call (`--release 17` has
 * no `HttpClient.close`), the `@generated` marker on line 1 of every file, and determinism.
 */
import { describe, expect, it } from "vitest"
import { realtime, sse, ws } from "../shared/__fixtures__/documents-streams.ts"
import { generateJavaSdk, type JavaSdkOptions } from "./sdk.ts"

type Json = Record<string, unknown>
type Files = Readonly<Record<string, string>>

const MARKER = "// @generated by honey. DO NOT EDIT."
const CLIENT = "src/main/java/ai/anyrow/AnyrowClient.java"
const TRANSPORT = "src/main/java/ai/anyrow/Transport.java"

/** The zero-op document: no path, so no operation. */
const ZERO: Json = { info: { title: "Anyrow", version: "1" }, openapi: "3.1.0", paths: {} }

const filesOf = (options?: JavaSdkOptions): Files => generateJavaSdk(ZERO, options).files

/* the emitted Gradle build: the java-library plugin, the defaults, --release 17, Maven Central, one dependency */
const BUILD_GRADLE = `// @generated by honey. DO NOT EDIT.
plugins {
    id 'java-library'
}

group = 'ai.anyrow'
version = '0.1.0'

tasks.withType(JavaCompile).configureEach {
    options.release = 17
    options.compilerArgs += ['-Xlint:all', '-Werror']
}

repositories {
    mavenCentral()
}

dependencies {
    api 'tools.jackson.core:jackson-databind:3.2.4'
}
`

const SETTINGS_GRADLE = `// @generated by honey. DO NOT EDIT.
rootProject.name = 'anyrow'
`

/* the client: the builder that takes the base URL and builds the one transport, and no operation */
const CLIENT_JAVA = `// @generated by honey. DO NOT EDIT.
package ai.anyrow;

import java.net.URI;

/** The client for the API. Build one with {@link #builder()}. */
public final class AnyrowClient {
  private final Transport transport;

  private AnyrowClient(Transport transport) {
    this.transport = transport;
  }

  /** A builder for a client; the base URL is required. */
  public static Builder builder() {
    return new Builder();
  }

  /** Builds an {@link AnyrowClient}. */
  public static final class Builder {
    private URI baseUrl;

    private Builder() {}

    /** Sets the base URL that every request resolves against. */
    public Builder baseUrl(String baseUrl) {
      this.baseUrl = URI.create(baseUrl);
      return this;
    }

    /** Builds the client; throws {@link IllegalStateException} when no base URL was set. */
    public AnyrowClient build() {
      if (baseUrl == null) {
        throw new IllegalStateException("baseUrl is required");
      }
      return new AnyrowClient(new Transport(baseUrl));
    }
  }
}
`

/* the transport: one HttpClient, built once, that follows no redirect on its own (R2 owns the follow loop) */
const TRANSPORT_JAVA = `// @generated by honey. DO NOT EDIT.
package ai.anyrow;

import java.net.URI;
import java.net.http.HttpClient;

/** The HTTP transport: one client, built once, which never follows a redirect on its own. */
final class Transport {
  private final URI baseUrl;
  private final HttpClient http;

  Transport(URI baseUrl) {
    this.baseUrl = baseUrl;
    this.http = HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();
  }
}
`

/** The emitted file names, in code-unit order: no `.editorconfig`, no Gradle wrapper. */
const FILE_NAMES = ["build.gradle", "settings.gradle", CLIENT, TRANSPORT]

/** The lines of `text` that open a field of the outer class: two spaces, then a declaration ending in `;`. */
const outerFields = (text: string) => text.split("\n").filter((line) => /^ {2}\S[^(]*;$/.test(line))

describe("generateJavaSdk: the zero-op package's files", () => {
	it("emits build.gradle, settings.gradle, the client and the transport, in code-unit order", () => {
		expect(Object.keys(filesOf())).toEqual(FILE_NAMES)
	})

	it("writes build.gradle byte for byte: the coordinates, --release 17, -Xlint:all -Werror, one Jackson dependency", () => {
		expect(filesOf()["build.gradle"]).toBe(BUILD_GRADLE)
	})

	it("writes settings.gradle byte for byte: the artifact id as the root project name", () => {
		expect(filesOf()["settings.gradle"]).toBe(SETTINGS_GRADLE)
	})

	it("writes the client byte for byte", () => {
		expect(filesOf()[CLIENT]).toBe(CLIENT_JAVA)
	})

	it("writes the transport byte for byte", () => {
		expect(filesOf()[TRANSPORT]).toBe(TRANSPORT_JAVA)
	})

	it("marks line 1 of every file @generated, and never writes <auto-generated", () => {
		const files = Object.entries(filesOf())
		expect({
			autoGenerated: files.filter(([, text]) => text.includes("<auto-generated")).map(([name]) => name),
			unmarked: files.filter(([, text]) => text.split("\n")[0] !== MARKER).map(([name]) => name),
		}).toEqual({ autoGenerated: [], unmarked: [] })
	})
})

describe("generateJavaSdk: the client's builder and state (R5)", () => {
	it("exposes builder(), baseUrl(String) and build() returning the client, in that shape", () => {
		const client = filesOf()[CLIENT] ?? ""
		expect(client).toContain("  public static Builder builder() {")
		expect(client).toContain("    public Builder baseUrl(String baseUrl) {")
		expect(client).toContain("    public AnyrowClient build() {")
	})

	it("keeps its state in one private final Transport, and no other field of the outer class", () => {
		expect(outerFields(filesOf()[CLIENT] ?? "")).toEqual(["  private final Transport transport;"])
	})

	it("builds the transport once, from the builder's base URL", () => {
		expect((filesOf()[CLIENT] ?? "").match(/new Transport\(/g)).toHaveLength(1)
		expect(filesOf()[CLIENT]).toContain("return new AnyrowClient(new Transport(baseUrl));")
	})
})

describe("generateJavaSdk: the transport (R1, R2)", () => {
	it("builds its HttpClient once, on followRedirects(NEVER)", () => {
		const transport = filesOf()[TRANSPORT] ?? ""
		expect({
			builds: transport.match(/HttpClient\.newBuilder\(\)/g)?.length,
			policy: transport.includes("followRedirects(HttpClient.Redirect.NEVER)"),
		}).toEqual({ builds: 1, policy: true })
	})

	it("calls no close(), shutdown() or awaitTermination() in any file, since HttpClient is not AutoCloseable before 21", () => {
		const calls = Object.values(filesOf()).flatMap(
			(text) => text.match(/\.(?:close|shutdown|awaitTermination)\(/g) ?? [],
		)
		expect(calls).toEqual([])
	})
})

describe("generateJavaSdk: determinism", () => {
	it("emits identical files for the default options given or omitted, and for the document's keys reordered", () => {
		const reordered = Object.fromEntries(Object.entries(ZERO).toReversed())
		expect([generateJavaSdk(ZERO, {}).files, generateJavaSdk(reordered).files, generateJavaSdk(ZERO).files]).toEqual([
			filesOf(),
			filesOf(),
			filesOf(),
		])
	})
})

/** The zero-op document with `schemas` as its components. */
const withSchemas = (schemas: Json): Json => ({ ...ZERO, components: { schemas } })

describe("generateJavaSdk: a model file each (phase b)", () => {
	it("writes a model that spells no imported type with no import block: the marker, the package, the declaration", () => {
		const files = generateJavaSdk(withSchemas({ Empty: { additionalProperties: false, type: "object" } })).files
		expect(files["src/main/java/ai/anyrow/Empty.java"]).toBe(
			`${MARKER}\npackage ai.anyrow;\n\npublic record Empty() {}\n`,
		)
	})

	it("writes no file for a component that declares no type, an alias of its use type", () => {
		const files = generateJavaSdk(withSchemas({ Tags: { items: { type: "string" }, type: "array" } })).files
		expect(Object.keys(files)).toEqual(FILE_NAMES)
	})
})

/** The WebSocket runtime's files, sorted. */
const WS_FILES = [
	"Keepalive.java",
	"Socket.java",
	"TypedWebSocket.java",
	"WsClose.java",
	"WsDial.java",
	"WsMessage.java",
]

/** The realtime runtime's files, sorted. */
const REALTIME_FILES = [
	"ConnectionState.java",
	"LongPollAdapter.java",
	"Realtime.java",
	"RealtimeLoop.java",
	"ResumableConnection.java",
	"SseAdapter.java",
	"TransportAdapter.java",
	"TransportConnection.java",
	"TransportKind.java",
	"TransportMessage.java",
	"TransportOptions.java",
	"WsAdapter.java",
]

/** The names of `set` among `files`. */
const names = (files: Files, set: readonly string[]) =>
	Object.keys(files)
		.map((path) => path.slice(path.lastIndexOf("/") + 1))
		.filter((name) => set.includes(name))

/** The SSE runtime's file names among `files`. */
const sseFiles = (files: Files) =>
	Object.keys(files)
		.map((path) => path.slice(path.lastIndexOf("/") + 1))
		.filter((name) => ["EventStream.java", "Pump.java", "Sse.java", "SseEvent.java"].includes(name))

describe("generateJavaSdk: a streaming operation (SSE from d1, WebSocket from d2a, realtime from d2b)", () => {
	/* new, the flip's end (ruling 6): SSE, WebSocket and realtime ops each emit their method; nothing stays refused */
	it("emits an SSE, a WebSocket and a realtime operation, each with its own method", () => {
		const resource = generateJavaSdk(sse()).files["src/main/java/ai/anyrow/TicksResource.java"] ?? ""
		const rooms = generateJavaSdk(ws()).files["src/main/java/ai/anyrow/RoomsResource.java"] ?? ""
		const feed = generateJavaSdk(realtime()).files["src/main/java/ai/anyrow/FeedResource.java"] ?? ""
		expect(resource).toMatch(/^ {2}public EventStream<Tick> stream\(TicksStreamParams params\) \{$/m)
		expect(rooms).toMatch(/^ {2}public TypedWebSocket socket\(RoomsSocketParams params\) \{$/m)
		expect(feed).toMatch(/^ {2}public ResumableConnection<Payload> live\(FeedLiveParams params\) \{$/m)
	})

	/* new: SSE is core (C#'s CORE set): its runtime ships with every operation SDK, none with a zero-op SDK */
	it("ships the SSE runtime files with every operation SDK and none with a zero-op SDK", () => {
		const plain = {
			...ZERO,
			paths: { "/x": { get: { operationId: "x.get", responses: { 204: { description: "done" } } } } },
		}
		const files = ["EventStream.java", "Pump.java", "Sse.java", "SseEvent.java"]
		expect({
			plain: sseFiles(generateJavaSdk(plain).files),
			sse: sseFiles(generateJavaSdk(sse()).files),
			zero: sseFiles(generateJavaSdk(ZERO).files),
		}).toEqual({ plain: files, sse: files, zero: [] })
	})

	/* new: C#'s sets (transport.ts:63): the WebSocket files with a ws or realtime op (realtime dials through them), the
	 * realtime files with a realtime op only, none of either otherwise */
	it("ships the WebSocket files with a WebSocket or realtime operation, and the realtime files with a realtime one only", () => {
		const of = (document: Readonly<Record<string, unknown>>) => {
			const files = generateJavaSdk(document).files
			return { realtime: names(files, REALTIME_FILES), ws: names(files, WS_FILES) }
		}
		expect({ realtime: of(realtime()), sse: of(sse()), ws: of(ws()), zero: of(ZERO) }).toEqual({
			realtime: { realtime: REALTIME_FILES, ws: WS_FILES },
			sse: { realtime: [], ws: [] },
			ws: { realtime: [], ws: WS_FILES },
			zero: { realtime: [], ws: [] },
		})
	})
})
